    late String svgString;
    switch (color) {
      case ApronFishStoreBodyColor.yellow:
        switch (pose) {
          case ApronFishStoreBodyPose.fishA:
            svgString = _fishStoreBodyYellowFishA;
          case ApronFishStoreBodyPose.fishB:
            svgString = _fishStoreBodyYellowFishB;
        }
      case ApronFishStoreBodyColor.navy:
        switch (pose) {
          case ApronFishStoreBodyPose.fishA:
            svgString = _fishStoreBodyNavyFishA;
          case ApronFishStoreBodyPose.fishB:
            svgString = _fishStoreBodyNavyFishB;
        }
      case ApronFishStoreBodyColor.blue:
        switch (pose) {
          case ApronFishStoreBodyPose.fishA:
            svgString = _fishStoreBodyBlueFishA;
          case ApronFishStoreBodyPose.fishB:
            svgString = _fishStoreBodyBlueFishB;
        }
    }
    return SvgPicture.string(
      svgString,
      height: height,
      width: width,
      colorMapper: colorMapper,
    );
  }
